const http = this.helpers.httpRequest;
const resp = await http({ method:'GET', url:'https://open.er-api.com/v6/latest/USD' });
const cop = resp.rates?.COP;
if (!cop) return [];

const UMBRAL_ALTO = 3300;
const UMBRAL_BAJO = 3100;
let text = null;

if (cop >= UMBRAL_ALTO) {
  text = `🚨 *TRM ALTA* 🚨\n\n💰 El dólar subió a *$${cop.toFixed(2)} COP*\n📈 Superó el umbral de $${UMBRAL_ALTO.toLocaleString()}\n\n⚡ TRM Alertas`;
} else if (cop <= UMBRAL_BAJO) {
  text = `🟢 *TRM BAJA* 🟢\n\n💰 El dólar bajó a *$${cop.toFixed(2)} COP*\n📉 Cayó por debajo de $${UMBRAL_BAJO.toLocaleString()}\n\nMomento ideal para importar/comprar USD.\n\n⚡ TRM Alertas`;
}

if (text) {
  await http({
    method:'POST',
    url:'http://148.230.90.171:8096/message/sendText/wasapea-7c7a2c6c',
    headers:{ 'apikey':'wasapea-evo-key-2026', 'Content-Type':'application/json' },
    body:{ number:'573106055920', text }
  });
  return { sent: true, alert: text };
}

return [];
